export function useProjectChat() {
  const { project } = useBuilderStore();

  const projectContext = project ? JSON.stringify(project.toStateObject()) : '';

  const { messages, input, handleInputChange, handleSubmit, isLoading, setMessages } = useChat({
    api: '/api/chat/project-consultant',
    body: {
      projectContext,
    },
    initialMessages: [],
  });

  const clearChat = () => {
    setMessages([]);
  };

  return {
    messages,
    input,
    handleInputChange,
    handleSubmit,
    isLoading,
    clearChat,
  };
}

