'use client';

import React from 'react';
import { useBuilderStore } from '@/hooks';
import { SectionGenerationControls } from './SectionGenerationControls';
import { GuidelineEditor } from './SectionGuidelineEditor';
import { SectionContextSelector } from './SectionContextSelector';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { SlidersHorizontal, StickyNote, Link as LinkIcon, Sparkles, Loader2, AlertCircle } from 'lucide-react';
import { useLocalization } from '@/context/LocalizationContext';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Button } from '@/components/ui/button';
import { useAiActions } from '@/hooks/report-mode/use-ai-actions';
import { ScrollArea } from '@/components/ui/scroll-area';

export function SectionGenerationPanel() {
    const { t } = useLocalization();
    const { project, selectedSectionId, userProfile } = useBuilderStore();
    const { generateSectionMutation, generateChapterMutation, generateProjectMutation } = useAiActions();

    const section = project?.getSection(selectedSectionId || '');

    if (!section) {
        return (
            <div className="flex flex-col items-center justify-center h-64 text-center p-6 bg-muted/30 rounded-lg border-2 border-dashed">
                <SlidersHorizontal className="h-12 w-12 text-muted-foreground mb-4 opacity-20" />
                <h3 className="text-lg font-semibold">No Section Selected</h3>
                <p className="text-sm text-muted-foreground mt-2">
                    Click on a section in the list to open its generation controls and configuration.
                </p>
            </div>
        );
    }

    const isGenerating = generateSectionMutation?.isPending && generateSectionMutation.variables === section.id;
    const isAnythingGenerating = generateSectionMutation?.isPending || generateChapterMutation.isPending || generateProjectMutation.isPending;
    const hasCredits = (userProfile?.credits ?? 0) >= 1;
    const canGenerate = hasCredits && !isAnythingGenerating;

    const handleGenerateClick = () => {
        if (canGenerate) {
            generateSectionMutation.mutate(section.id);
        }
    };

    return (
        <div className="flex flex-col h-full -mx-4">
            <div className="px-6 py-4 border-b bg-card/50 sticky top-0 z-10">
                <div className="flex items-center justify-between mb-1">
                    <span className="text-xs font-bold text-primary tracking-widest uppercase">Section Editing</span>
                </div>
                <h2 className="text-lg font-bold truncate">{section.title}</h2>
            </div>

            <ScrollArea className="flex-1">
                <div className="p-6">
                    <Tabs defaultValue="controls" className="w-full">
                        <TooltipProvider>
                            <TabsList className="grid w-full grid-cols-3 mb-8">
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <TabsTrigger value="controls" className="data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
                                            <SlidersHorizontal className="h-4 w-4" />
                                        </TabsTrigger>
                                    </TooltipTrigger>
                                    <TooltipContent><p>Controls</p></TooltipContent>
                                </Tooltip>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <TabsTrigger value="prompt" className="data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
                                            <StickyNote className="h-4 w-4" />
                                        </TabsTrigger>
                                    </TooltipTrigger>
                                    <TooltipContent><p>Edit Prompt</p></TooltipContent>
                                </Tooltip>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <TabsTrigger value="context" className="data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
                                            <LinkIcon className="h-4 w-4" />
                                        </TabsTrigger>
                                    </TooltipTrigger>
                                    <TooltipContent><p>{t('builder.reportGenerator.tool_tab_context')}</p></TooltipContent>
                                </Tooltip>
                            </TabsList>
                        </TooltipProvider>

                        <TabsContent value="controls" className="space-y-6 mt-0">
                            <SectionGenerationControls section={section} />
                        </TabsContent>

                        <TabsContent value="prompt" className="mt-0">
                            <GuidelineEditor itemKey={section.id} />
                        </TabsContent>

                        <TabsContent value="context" className="mt-0">
                            <SectionContextSelector sectionId={section.id} />
                        </TabsContent>
                    </Tabs>
                </div>
            </ScrollArea>

            <div className="p-6 border-t bg-card/50 sticky bottom-0 z-10">
                <TooltipProvider>
                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                onClick={handleGenerateClick}
                                disabled={!canGenerate}
                                className="w-full h-12 text-md font-bold shadow-lg shadow-primary/20 transition-all active:scale-[0.98]"
                            >
                                {isGenerating ? (
                                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                                ) : (
                                    <Sparkles className="mr-2 h-5 w-5" />
                                )}
                                {t('builder.reportGenerator.generateButton')}
                            </Button>
                        </TooltipTrigger>
                        {!canGenerate && (
                            <TooltipContent side="top">
                                <p className="flex items-center gap-2">
                                    <AlertCircle className="h-4 w-4 text-destructive" />
                                    {isAnythingGenerating ? "Another generation is in progress." : "Insufficient credits."}
                                </p>
                            </TooltipContent>
                        )}
                    </Tooltip>
                </TooltipProvider>
            </div>
        </div>
    );
}

