                        aria-label={`Select section ${section.title}`}
                    />
                </div>
            )}

            <div className="flex items-center gap-3 flex-1 min-w-0">
                <div {...listeners} className="p-1 cursor-grab active:cursor-grabbing touch-none -ml-2 text-muted-foreground transition-colors hover:text-foreground">
                    <GripVertical className="h-5 w-5" />
                </div>

                <div className="flex flex-col flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                        <span className="text-[10px] font-mono font-bold text-muted-foreground bg-muted px-1.5 py-0.5 rounded uppercase tracking-wider">
                            {chapterIndex >= 0 ? `${chapterIndex + 1}.${sectionIndex + 1}`: `${sectionIndex + 1}`}
                        </span>
                        <span className={cn(
                            "font-medium truncate",
                            isSelectedForEdit && "text-primary font-bold"
                        )}>
                            {section.title}
                        </span>
                        {isGenerating && <Loader2 className="h-3.5 w-3.5 animate-spin text-primary" />}
                    </div>

                    <div className="flex items-center gap-3 mt-1">
                        {totalContext > 0 && (
                            <TooltipProvider>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <div className="flex items-center gap-1">
                                            <LinkIcon className="h-3 w-3 text-primary" />
                                            <span className="text-[10px] text-primary font-bold">{totalContext} {t('builder.reportGenerator.context_label', { count: totalContext })}</span>
                                        </div>
                                    </TooltipTrigger>
                                    <TooltipContent side="bottom" align="start">
                                        <div className="text-xs space-y-1 py-1">
                                            <p className="font-bold border-b pb-1 mb-1">Contextual References:</p>
                                            {contextNames.map(name => <p key={name} className="flex items-center gap-2">• {name}</p>)}
                                        </div>
                                    </TooltipContent>
                                </Tooltip>
                            </TooltipProvider>
                        )}
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                <TooltipProvider>
                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                variant={isSelectedForEdit ? "default" : "ghost"}
                                size="icon"
                                className="h-8 w-8 rounded-full"
                                onClick={handleOpenControls}
                            >
                                <Settings2 className="h-4 w-4" />
                            </Button>
                        </TooltipTrigger>
                        <TooltipContent><p>Configure Section</p></TooltipContent>
                    </Tooltip>

                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                variant="ghost"
                                size="icon"
                                className="h-8 w-8 rounded-full text-primary hover:text-primary hover:bg-primary/10"
                                onClick={handleGenerateClick}
                                disabled={!canGenerate}
                            >
                                {isGenerating ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}
                            </Button>
                        </TooltipTrigger>
                        <TooltipContent>
                            <p>{!canGenerate ? (isAnythingGenerating ? "Wait for other tasks..." : "Insufficient credits") : t('builder.reportGenerator.generateButton')}</p>
                        </TooltipContent>
                    </Tooltip>
                </TooltipProvider>
            </div>
        </div>
    </div>
);

