'use client';

import React, { useRef, useEffect } from 'react';
import { useSpring, animated } from '@react-spring/web';
import { useGesture } from '@use-gesture/react';
import { cn } from '@/lib/utils/cn';

interface FigmaCanvasProps {
  children: React.ReactNode;
  zoomLevel: number;
  setZoomLevel: (zoom: number) => void;
}

export function FigmaCanvas({ children, zoomLevel, setZoomLevel }: FigmaCanvasProps) {
  const targetRef = useRef<HTMLDivElement>(null);

  const [{ x, y, scale }, api] = useSpring(() => ({
    x: 0,
    y: 0,
    scale: zoomLevel,
    config: { mass: 1, tension: 280, friction: 60 },
  }));

  // Sync zoomLevel prop with spring scale
  useEffect(() => {
    api.start({ scale: zoomLevel });
  }, [zoomLevel, api]);

  useGesture(
    {
      onDrag: ({ offset: [dx, dy] }) => {
        api.start({ x: dx, y: dy });
      },
      onPinch: ({ offset: [dScale], origin: [ox, oy] }) => {
        setZoomLevel(dScale);
      },
      onWheel: ({ event, active }) => {
        if (event.ctrlKey) {
           // Zoom on ctrl+wheel
        }
      }
    },
    {
      target: targetRef,
      drag: { from: () => [x.get(), y.get()] },
      pinch: { scaleBounds: { min: 0.1, max: 3 }, from: () => [scale.get(), 0] },
      eventOptions: { passive: false }
    }
  );

  return (
    <div 
      className="relative w-full h-full overflow-hidden bg-[#1E1E1E] cursor-grab active:cursor-grabbing"
      ref={targetRef}
      style={{ touchAction: 'none' }}
    >
      {/* Figma Dot Grid */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-20"
        style={{
          backgroundImage: 'radial-gradient(circle, #444 1px, transparent 1px)',
          backgroundSize: `${20 * zoomLevel}px ${20 * zoomLevel}px`,
          transform: `translate(${x.get() % (20 * zoomLevel)}px, ${y.get() % (20 * zoomLevel)}px)`
        }}
      />

      <animated.div
        style={{
          x,
          y,
          scale,
          transformOrigin: '0 0',
        }}
        className="absolute top-0 left-0 p-[200px]"
      >
        <div className="flex flex-col gap-20 items-center">
          {children}
        </div>
      </animated.div>
    </div>
  );
}

