'use client';

import React from 'react';
import { useBuilderStore } from '@/hooks';
import { cn } from '@/lib/utils/cn';
import { ChevronRight, ChevronDown, FileText, Folder, Eye, EyeOff, Lock, Unlock } from 'lucide-react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Button } from '@/components/ui/button';

export function LayersSidebar() {
  const { project, selectedSectionId, setSelectedSection } = useBuilderStore();
  const [expandedChapters, setExpandedChapters] = React.useState<Record<string, boolean>>({});

  const toggleChapter = (chapterId: string) => {
    setExpandedChapters(prev => ({ ...prev, [chapterId]: !prev[chapterId] }));
  };

  if (!project) return null;

  return (
    <aside className="w-64 border-r bg-[#1E1E1E] text-[#B3B3B3] flex flex-col h-full select-none">
      <div className="px-4 py-3 border-b border-[#333] flex items-center justify-between">
        <span className="text-xs font-bold uppercase tracking-wider text-white">Layers</span>
        <div className="flex gap-1">
           <Button variant="ghost" size="icon" className="h-6 w-6 text-[#B3B3B3] hover:text-white hover:bg-[#333]">
             <Eye className="h-3.5 w-3.5" />
           </Button>
        </div>
      </div>

      <ScrollArea className="flex-1">
        <div className="py-2">
          {project.content.map((chapter, chapterIndex) => {
            const isExpanded = expandedChapters[chapter.id] !== false; // Default expanded
            return (
              <div key={chapter.id} className="mb-1">
                <div 
                  className="flex items-center gap-1 px-2 py-1.5 hover:bg-[#2C2C2C] cursor-pointer group"
                  onClick={() => toggleChapter(chapter.id)}
                >
                  {isExpanded ? <ChevronDown className="h-3.5 w-3.5" /> : <ChevronRight className="h-3.5 w-3.5" />}
                  <Folder className="h-4 w-4 text-[#F2C94C]" />
                  <span className="text-sm truncate flex-1 font-medium">{chapter.title || `Chapter ${chapterIndex + 1}`}</span>
                </div>

                {isExpanded && (
                  <div className="ml-4 border-l border-[#333]">
                    {chapter.sections.map((section, sectionIndex) => (
                      <div 
                        key={section.id}
                        className={cn(
                          "flex items-center gap-2 px-3 py-1.5 cursor-pointer transition-colors group",
                          selectedSectionId === section.id ? "bg-[#0C8CE9] text-white" : "hover:bg-[#2C2C2C]"
                        )}
                        onClick={() => setSelectedSection(section.id)}
                      >
                        <FileText className={cn("h-4 w-4", selectedSectionId === section.id ? "text-white" : "text-[#B3B3B3]")} />
                        <span className="text-sm truncate flex-1">
                          {section.title || `Section ${sectionIndex + 1}`}
                        </span>
                        <div className="opacity-0 group-hover:opacity-100 flex items-center gap-1">
                           <Eye className="h-3 w-3" />
                           <Lock className="h-3 w-3" />
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </ScrollArea>
    </aside>
  );
}

'use client';

import React from 'react';
import { useBuilderStore } from '@/hooks';
import { ScrollArea } from '@/components/ui/scroll-area';
import { SectionGenerationPanel } from '../section-controls/SectionGenerationPanel';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { SlidersHorizontal, Settings, Info, Box } from 'lucide-react';

export function InspectorSidebar() {
  const { selectedSectionId } = useBuilderStore();

  return (
    <aside className="w-72 border-l bg-[#1E1E1E] text-[#B3B3B3] flex flex-col h-full select-none">
      <div className="px-4 py-3 border-b border-[#333] flex items-center justify-between">
        <span className="text-xs font-bold uppercase tracking-wider text-white">Inspector</span>
        <Box className="h-4 w-4" />
      </div>

      <Tabs defaultValue="design" className="flex-1 flex flex-col">
        <TabsList className="w-full bg-transparent border-b border-[#333] rounded-none h-10 px-0">
          <TabsTrigger value="design" className="flex-1 rounded-none data-[state=active]:bg-transparent data-[state=active]:text-white data-[state=active]:border-b-2 data-[state=active]:border-[#0C8CE9] text-xs">Design</TabsTrigger>
          <TabsTrigger value="prototype" className="flex-1 rounded-none data-[state=active]:bg-transparent data-[state=active]:text-white data-[state=active]:border-b-2 data-[state=active]:border-[#0C8CE9] text-xs">AI Config</TabsTrigger>
          <TabsTrigger value="inspect" className="flex-1 rounded-none data-[state=active]:bg-transparent data-[state=active]:text-white data-[state=active]:border-b-2 data-[state=active]:border-[#0C8CE9] text-xs">Inspect</TabsTrigger>
        </TabsList>

        <ScrollArea className="flex-1">
          <TabsContent value="design" className="m-0">
             {selectedSectionId ? (
                <SectionGenerationPanel />
             ) : (
                <div className="p-8 text-center opacity-40 flex flex-col items-center gap-4">
                  <Settings className="h-12 w-12" />
                  <p className="text-sm">Select a section to view its properties</p>
                </div>
             )}
          </TabsContent>
          <TabsContent value="prototype" className="p-4 m-0">
             <p className="text-xs">Advanced AI settings coming soon...</p>
          </TabsContent>
          <TabsContent value="inspect" className="p-4 m-0">
             <p className="text-xs">Section Metadata and Token Usage</p>
          </TabsContent>
        </ScrollArea>
      </Tabs>
    </aside>
  );
}

'use client';

import React from 'react';
import { Button } from '@/components/ui/button';
import { 
  MousePointer2, 
  Hand, 
  Square, 
  Type, 
  Image as ImageIcon, 
  Share2, 
  Play, 
  Plus, 
  ChevronDown,
  Monitor,
  Layout
} from 'lucide-react';
import { cn } from '@/lib/utils/cn';
import { useLocalization } from '@/context/LocalizationContext';

interface TopToolbarProps {
  zoomLevel: number;
  setZoomLevel: (zoom: number) => void;
  projectName: string;
}

export function TopToolbar({ zoomLevel, setZoomLevel, projectName }: TopToolbarProps) {
  const { t } = useLocalization();

  return (
    <header className="h-12 border-b bg-[#1E1E1E] text-white flex items-center justify-between px-4 fixed top-0 left-0 right-0 z-50 select-none">
      <div className="flex items-center gap-4">
        <div className="flex items-center gap-0.5">
          <div className="p-1.5 hover:bg-[#333] rounded cursor-pointer text-[#0C8CE9]">
            <Layout className="h-5 w-5" />
          </div>
          <div className="h-4 w-[1px] bg-[#333] mx-1" />
          <ToolButton icon={<MousePointer2 className="h-4 w-4" />} active />
          <ToolButton icon={<Hand className="h-4 w-4" />} />
          <ToolButton icon={<Square className="h-4 w-4" />} />
          <ToolButton icon={<Layout className="h-4 w-4" />} />
          <ToolButton icon={<Type className="h-4 w-4" />} />
          <ToolButton icon={<ImageIcon className="h-4 w-4" />} />
        </div>
      </div>

      <div className="absolute left-1/2 -translate-x-1/2 font-medium text-sm text-[#B3B3B3] hover:text-white cursor-pointer transition-colors">
        {projectName || 'Untitled Document'}
      </div>

      <div className="flex items-center gap-3">
        <div className="flex items-center gap-1 px-2 py-1 rounded hover:bg-[#333] cursor-pointer group">
          <span className="text-xs font-medium">{Math.round(zoomLevel * 100)}%</span>
          <ChevronDown className="h-3 w-3 text-[#B3B3B3] group-hover:text-white" />
        </div>

        <div className="h-4 w-[1px] bg-[#333] mx-1" />

        <Button variant="ghost" size="sm" className="text-white hover:bg-[#333] gap-2 h-8">
          <Share2 className="h-4 w-4" />
          <span className="text-xs">Share</span>
        </Button>

        <Button size="sm" className="bg-[#0C8CE9] hover:bg-[#0A74C2] text-white gap-2 h-8 px-4">
          <Play className="h-3.5 w-3.5 fill-current" />
          <span className="text-xs font-bold uppercase">Present</span>
        </Button>
      </div>
    </header>
  );
}

function ToolButton({ icon, active }: { icon: React.ReactNode; active?: boolean }) {
  return (
    <div className={cn(
      "p-2 hover:bg-[#333] rounded cursor-pointer transition-colors",
      active ? "text-[#0C8CE9]" : "text-[#B3B3B3]"
    )}>
      {icon}
    </div>
  );
}

