const renderFrames = () => {
  if (!project) return null;

  return project.content.map((chapter, chapterIndex) => (
    <div key={chapter.id} className="flex flex-col gap-10">
      <div className="flex items-center gap-4">
        <h2 className="text-3xl font-bold text-white/20 select-none">Chapter {chapterIndex + 1}: {chapter.title}</h2>
        <div className="h-[2px] flex-1 bg-white/5" />
      </div>

      <div className="flex flex-wrap gap-20 justify-center">
        {chapter.sections.map((section, sectionIndex) => (
          <div key={section.id} className="flex flex-col gap-4">
             <div className="flex items-center justify-between px-2">
                <span className="text-xs font-bold text-white/30 uppercase tracking-widest">{chapterIndex + 1}.{sectionIndex + 1} {section.title}</span>
             </div>
             <A4Page 
               className={cn(
                 "shadow-2xl transition-all duration-300 transform-gpu",
                 selectedSectionId === section.id ? "ring-4 ring-[#0C8CE9] ring-offset-8 ring-offset-[#1E1E1E] scale-[1.02]" : "hover:scale-[1.01]"
               )}
               onClick={() => setSelectedSection(section.id)}
             >
               <div className="p-8 h-full overflow-hidden bg-white dark:bg-slate-950">
                  <MarkdownViewer content={section.content || `*Empty section: ${section.title}*`} />
               </div>
             </A4Page>
          </div>
        ))}
      </div>
    </div>
  ));
};

return (
  <div className="flex flex-col gap-32 pb-64 pt-32 px-32">
     {/* Cover Page Frame */}
     <div className="flex flex-col gap-4 items-center">
        <span className="text-xs font-bold text-white/30 uppercase tracking-widest">Document Cover</span>
        <A4Page className="shadow-2xl">
          <CoverPage project={project} />
        </A4Page>
     </div>

     {/* Content Frames */}
     {renderFrames()}

     {!hasContent && (
       <div className="flex items-center justify-center min-h-[500px]">
         <ReportSteps />
       </div>
     )}
  </div>
);

