  94     if (!project || !project.sections) return "Start by adding a chapter or applying a template.";
  95     const emptySection = project.sections.find(s => !s.content);
  96     if (emptySection) {
  97         return `Suggestion: Try generating the "${emptySection.title}" section next.`;
  98     }
  99     return "All sections have content. You can now review or export your document.";
 100   };
 101   const suggestion = getSuggestion();
 102 
 103   const renderFrames = () => {
 104     if (!project) return null;
