 112               <h2 className="text-3xl font-bold text-white/20 select-none">Chapter {index + 1}: {chapter.title}</h2>
 113               <div className="h-[2px] flex-1 bg-white/5" />
 114             </div>
 115             
 116             <div className="flex flex-wrap gap-20 justify-center">
 117               {chapter.sections.map((section, sectionIndex) => (
