 141                <div className="flex items-center justify-between px-2 w-full max-w-[210mm]">
 142                   <span className="text-xs font-bold text-white/30 uppercase tracking-widest">{index + 1} {section.title}</span>
 143                </div>
 144                <div className={cn(
 145                    "relative transition-all duration-300 transform-gpu",
 146                    selectedSectionId === section.id ? "ring-4 ring-[#0C8CE9] ring-offset-8 ring-offset-[#1E1E1E] scale-[1.02]" : "hover:scale-[1.01]"
 147                )}>
 148                    <A4Page className="shadow-2xl">
 149                      <div className="p-8 h-full overflow-hidden bg-white dark:bg-slate-950">
 150                         <MarkdownViewer content={section.content || `*Empty section: ${section.title}*`} />
 151                      </div>
 152                    </A4Page>
 153                </div>
 154             </div>
 155         )
 156       }
 157       return null;
 158     });
 159   };
 160 
 161   return (
 162     <div className="flex flex-col gap-32 pb-64 pt-32 px-32">
 163        {/* Cover Page Frame */}
 164        <div className="flex flex-col gap-4 items-center">
 165           <span className="text-xs font-bold text-white/30 uppercase tracking-widest">Document Cover</span>
 166           <A4Page className="shadow-2xl">
 167             <CoverPage project={project} />
 168           </A4Page>
 169        </div>
 170 
 171        {/* Content Frames */}
 172        {renderFrames()}
 173 
 174        {!hasContent && (
 175          <div className="flex items-center justify-center min-h-[500px]">
 176            <ReportSteps />
 177          </div>
 178        )}
 179     </div>
 180   );
 181 };
 182 
 183 export default ReportResults;
 184 
